--
-- Table structure for table `bet_submissions`
--

DROP TABLE IF EXISTS `bet_submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bet_submissions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `site_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `issue_no` varchar(40) NOT NULL,
  `source_text` text,
  `formatted_text` text,
  `submission_fingerprint` char(64) DEFAULT NULL,
  `bet_count` int NOT NULL DEFAULT '0',
  `amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `win_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `sealed` tinyint NOT NULL DEFAULT '0',
  `placed_at` datetime NOT NULL,
  `refunded_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_submission_user_time` (`site_id`,`user_id`,`placed_at`),
  KEY `idx_submission_issue` (`site_id`,`issue_no`),
  KEY `idx_submission_fingerprint` (`site_id`,`user_id`,`submission_fingerprint`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

