--
-- Table structure for table `organization_credit_ledger`
--

DROP TABLE IF EXISTS `organization_credit_ledger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `organization_credit_ledger` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `transaction_no` varchar(48) NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `site_id` bigint unsigned NOT NULL,
  `organization_id` bigint unsigned DEFAULT NULL,
  `account_type` varchar(24) NOT NULL,
  `account_id` bigint unsigned NOT NULL,
  `related_user_id` bigint unsigned DEFAULT NULL,
  `related_bet_record_id` bigint unsigned DEFAULT NULL,
  `related_bet_detail_id` bigint unsigned DEFAULT NULL,
  `issue_no` varchar(40) DEFAULT NULL,
  `direction` varchar(8) NOT NULL,
  `amount` decimal(18,2) NOT NULL,
  `balance_before` decimal(18,2) NOT NULL DEFAULT '0.00',
  `balance_after` decimal(18,2) NOT NULL DEFAULT '0.00',
  `reason` varchar(120) NOT NULL,
  `source_type` varchar(40) NOT NULL,
  `category` varchar(40) DEFAULT 'other',
  `operator_type` varchar(24) DEFAULT NULL,
  `operator_id` bigint unsigned DEFAULT NULL,
  `operator_name` varchar(80) DEFAULT NULL,
  `counterparty_account_type` varchar(24) DEFAULT NULL,
  `counterparty_account_id` bigint unsigned DEFAULT NULL,
  `note` varchar(500) DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_score_ledger_transaction_account` (`transaction_no`,`account_type`,`account_id`,`direction`),
  KEY `idx_credit_ledger_account` (`site_id`,`account_type`,`account_id`,`created_at`),
  KEY `idx_credit_ledger_bet` (`related_bet_record_id`,`related_bet_detail_id`),
  KEY `idx_score_ledger_search` (`tenant_id`,`site_id`,`source_type`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=643 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

